 kded/CMakeLists.txt |  2 ++
 kded/service.cpp    | 41 +++++++++++++++++++++++++++++++++++++++++
 kded/service.h      |  2 ++
 libs/handler.cpp    |  6 +++---
 5 files changed, 49 insertions(+), 3 deletions(-)

