diff --git a/kded/service.cpp b/kded/service.cpp
index 18754fc37..6d7ed357e 100644
--- a/kded/service.cpp
+++ b/kded/service.cpp
@@ -11,11 +11,17 @@

 #include <KPluginFactory>

+#include "configuration.h"
 #include "connectivitymonitor.h"
+#include "handler.h"
 #include "monitor.h"
 #include "notification.h"
 #include "secretagent.h"

+#include <KGlobalAccel>
+#include <KLocalizedString>
+
+#include <QAction>
 #include <QDBusConnection>
 #include <QDBusConnectionInterface>
 #include <QDBusMetaType>
@@ -31,6 +37,8 @@ public:
     Notification *notification = nullptr;
     Monitor *monitor = nullptr;
     ConnectivityMonitor *connectivityMonitor = nullptr;
+    Handler *handler = nullptr;
+    QAction *airplaneModeAction = nullptr;
 };

 NetworkManagementService::NetworkManagementService(QObject *parent, const QVariantList &)
@@ -70,6 +78,39 @@ void NetworkManagementService::init()
                 d->connectivityMonitor,
                 &ConnectivityMonitor::cancelLimitedConnectivityNotificationTimer);
     }
+
+    if (!d->airplaneModeAction) {
+        d->airplaneModeAction = new QAction(i18nc("@action global shortcut", "Toggle Airplane Mode"), this);
+        d->airplaneModeAction->setObjectName(QStringLiteral("Toggle Airplane Mode"));
+        d->airplaneModeAction->setProperty("componentName", QStringLiteral("plasma-nm"));
+        d->airplaneModeAction->setProperty("componentDisplayName", i18nc("@title name of the global shortcuts category", "Networking"));
+        KGlobalAccel::self()->setGlobalShortcut(d->airplaneModeAction, Qt::Key_WLAN);
+        connect(d->airplaneModeAction, &QAction::triggered, this, &NetworkManagementService::toggleAirplaneMode);
+    }
+}
+
+void NetworkManagementService::toggleAirplaneMode()
+{
+    Q_D(NetworkManagementService);
+
+    if (!d->handler) {
+        d->handler = new Handler(this);
+    }
+
+    const bool enable = !Configuration::self().airplaneModeEnabled();
+    d->handler->enableAirplaneMode(enable);
+    Configuration::self().setAirplaneModeEnabled(enable);
+
+    QDBusMessage osd = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
+                                                      QStringLiteral("/org/kde/osdService"),
+                                                      QStringLiteral("org.kde.osdService"),
+                                                      QStringLiteral("showText"));
+    if (enable) {
+        osd << QStringLiteral("network-flightmode-on") << i18nc("airplane mode was enabled, keep short", "Airplane Mode On");
+    } else {
+        osd << QStringLiteral("network-flightmode-off") << i18nc("airplane mode was disabled, keep short", "Airplane Mode Off");
+    }
+    QDBusConnection::sessionBus().asyncCall(osd);
 }

 #include "service.moc"
